import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>100KB是网上最实用的文件大小。它小到能通过任何上传表单，又大到看起来依然好看。</p>\n<p>简历、招聘网站、博客缩略图和邮件配图，都能在100KB下活得很好。这就是画质和便利相遇的尺寸。</p>\n<p>这篇指南会讲清楚100KB为什么赢得了这个名声、压缩怎么做到它，以及怎样得到最清晰的结果。</p>\n<h2 id=\"why-100kb-is-the-sweet-spot\">为什么100KB是黄金尺寸？</h2>\n<p>大多数上传表单把上限设在50KB到500KB之间。100KB的文件几乎不用多想就能通过所有这些表单。</p>\n<p>同时，100KB装得下足够的数据，让照片看起来干净。脸部自然、文字可读、颜色平滑。</p>\n<p>这个数字对慢速网络也很友好。100KB的图片即使在信号很弱的手机上，也只要零点几秒就能加载出来。</p>\n<p>这种组合很少见。更小的尺寸更难看，更大的尺寸更容易被拒绝，100KB正好卡在中间。</p>\n<h2 id=\"what-fits-in-100kb\">100KB里能装下什么？</h2>\n<p>证件照放进去很轻松。正常网页尺寸下的人像在100KB里能保留细节，包括头发、眼镜和衣服的纹理。</p>\n<p>博客缩略图也可以。1200像素宽的头图压到100KB，在它实际出现的任何屏幕上看起来都很锐利。</p>\n<p>截图在100KB下也很舒服。界面文字保持清晰，而文字正是最先在更小尺寸下出问题的东西。</p>\n<p>只有细节特别多的图片会吃力。密集的信息图或满是细叶的宽幅风景，可能需要200KB才能保持清晰。</p>\n<h2 id=\"how-the-100kb-tool-works\">100KB工具是怎么工作的？</h2>\n<p><a href=\"/zh/tupian-yasuo-dao-100kb/\">图片压缩到100KB工具</a>完全在你的浏览器里运行。图片永远不会上传到服务器。</p>\n<p>它用的是二分画质搜索。工具会测试不同的画质档位，逐步逼近既能塞进100KB、画质又最高的那一个设置。</p>\n<p>画质优先。只有降低画质还达不到目标时，工具才会缩小像素尺寸。</p>\n<p>支持最大25MB的输入，包括JPG、PNG、WebP和HEIC文件。手机相机直出的照片直接用就行。</p>\n<h2 id=\"quality-at-100kb\">100KB下的画质</h2>\n<p>大多数观众分不出100KB的照片和原图。差别只有放大了仔细看才能发现。</p>\n<p>肤色是最好的测试。100KB下肤色依然平滑自然，不会出现50KB下那种斑驳的色块。</p>\n<p>锐利的边缘也保得住。眼镜框、首饰和印刷文字在这个尺寸下依然清晰。</p>\n<p>背景是唯一要留意的地方。平滑渐变的天空可能会出现淡淡的色带，不过在100KB下很轻微。</p>\n<h2 id=\"jpg-vs-png-vs-webp-100kb\">100KB下JPG、PNG、WebP对比</h2>\n<p>JPG是100KB下照片的默认选择。它到处都被接受，处理平滑色调也很出色。</p>\n<p>WebP在同样大小下常常会干净一点点。缺点是兼容性：有些老旧的报名网站和系统不接受WebP文件。</p>\n<p>PNG适合图形，不适合照片。颜色扁平的标志或图表用PNG依然锐利，但照片用PNG会浪费预算。</p>\n<p>工具可以把大PNG自动转成JPG或WebP。光是打开这个开关，就常常能让一次失败的压缩变成干净的通过。</p>\n<h2 id=\"resumes-and-job-portals\">简历和招聘网站</h2>\n<p>招聘网站是人们需要100KB最常见的原因。简历照片、作品样本或证书扫描，面对的都是同一个上限。</p>\n<p>100KB的证件照看起来很专业。招聘方看到的是一张清晰的脸，而不是一个糊成马赛克的方块，这比人们承认的更重要。</p>\n<p>证书扫描要格外小心。上面细小的印刷文字必须保持可读，提交前先预览并放大检查。</p>\n<p>网站接受WebP时，照片就用WebP。如果它只列了JPG，那就坚持用JPG，让画质搜索去干活。</p>\n<h2 id=\"websites-and-blogs\">网站和博客</h2>\n<p>100KB的博客缩略图加载快、看起来也锐利。一个页面有十张缩略图，总共大约1MB，大多数网络都轻松应付。</p>\n<p>搜索引擎奖励加载快的页面。图片通常是页面最重的部分，把它们控制在100KB左右，能直接改善加载时间。</p>\n<p>首图可以更大一点，但配图很少需要更大。一张100KB的配图，对大多数读者来说在画质上是看不出差别的。</p>\n<p>想做整站的图片优化，可以把100KB工具和<a href=\"/zh/wangye-tupian-youhua/\">网页图片优化工具</a>搭配使用，后者还提供预设和可以直接粘贴的HTML代码。</p>\n<h2 id=\"email-and-newsletters\">邮件和电子报</h2>\n<p>邮件客户端渲染大图片很慢。100KB的图片在收件箱里几乎瞬间出现，2MB的图片却可能卡住。</p>\n<p>带多张图片的电子报受益最大。五张100KB的图片总共500KB，整封邮件依然很轻。</p>\n<p>邮件里的格式越简单越好。JPG是最安全的选择，因为有些邮件客户端处理WebP很差。</p>\n<p>发之前先给自己发一封测试邮件。检查图片加载得快不快，有没有拉伸或模糊的地方。</p>\n<h2 id=\"batch-compression\">一次把多张图片压到100KB</h2>\n<p>你可以把一整个文件夹的图片一次性批量压到100KB。全部拖进来，每张都会按同一个目标处理。</p>\n<p>结果一起打包成ZIP下载。这样一组缩略图或作品照片就整整齐齐地放在一个地方。</p>\n<p>批量模式最适合博客迁移。五十张旧缩略图一张一张转要花一下午，批量处理几分钟就够了。</p>\n<p>下载整个ZIP之前，先抽查几张结果。如果某张看起来发虚，单独调整它的格式再跑一次。</p>\n<h2 id=\"common-mistakes\">100KB下常见的错误</h2>\n<p>最大的错误，是从已经压缩过的文件开始。每一轮压缩都会叠加损伤，所以一定要用原图。</p>\n<p>给照片锁定PNG格式也是一个错误。细节丰富的照片用PNG很难干净地到达100KB，工具会提醒你。</p>\n<p>忘记检查结果也很常见。文件大小对了，图片却可能是糊的，所以下载之前先预览。</p>\n<p>最后，别以为每个网站都接受WebP。先确认接受的格式，不然你可能要压缩两次。</p>\n<h2 id=\"when-100kb-is-not-enough\">什么时候100KB不够用？</h2>\n<p>细节多的大图有时需要更多空间。一张标签细密的宽幅信息图，在100KB下可能依然模糊。</p>\n<p>打印也需要更多。打算印到纸上的照片要保持高分辨率，而100KB是网页尺寸，不是打印尺寸。</p>\n<p>遇到这种情况，就升级到<a href=\"/zh/tupian-yasuo-dao-200kb/\">200KB压缩工具</a>或<a href=\"/zh/tupian-yasuo-dao-500kb/\">500KB压缩工具</a>。</p>\n<p>规则始终不变：用你的场景允许的最大尺寸。条件允许时，多出来的KB换来的画质是值得的。</p>\n<h2 id=\"under-100kb-badge\">“小于100KB”徽章能保证什么？</h2>\n<p>压缩成功后，工具会显示“小于100KB”徽章。这个徽章表示最终文件的精确字节数低于100KB。</p>\n<p>按字节精确测量很重要，因为报名网站检查的是字节数，不是四舍五入后的数字。手机上显示100KB的文件，实际可能是100.4KB。</p>\n<p>工具会故意瞄准上限以下一点点，通常落在98KB到99.9KB之间。这个余量能帮你避开四舍五入的差异。</p>\n<p>如果徽章没有出现，说明文件没达到目标。工具会诚实地告诉你，而不是递给你一个会被拒绝的文件。</p>\n<p>没有徽章的文件千万别提交。换个格式快速重试一次，远比上传被拒要好。</p>\n<h2 id=\"dimension-scaling-100kb\">100KB下尺寸缩放是怎么工作的？</h2>\n<p>只降画质达不到100KB时，尺寸缩放会缩小图片的像素尺寸。它是一小步一小步地降，而不是一下子跳到底。</p>\n<p>工具会测试90%、80%等缩放比例，在第一个能塞进目标的比例停下来。每一步都尽量保留最多的尺寸。</p>\n<p>小幅度的缩放通常看不出来。显示出来800像素宽的照片，720像素宽看起来一模一样。</p>\n<p>缩放对特别大的原图帮助最大。一张4000像素宽的照片，像素远超任何屏幕的需要，裁掉一点根本看不出来。</p>\n<p>如果报名网站要求精确像素，你也可以锁定尺寸。工具会更努力地只调画质，目标达不到时也会提醒你。</p>\n<h2 id=\"social-media-100kb\">社交媒体和头像用100KB</h2>\n<p>社交平台会对你的上传再压缩一次，所以从100KB的干净文件开始，效果反而更好。巨大的原图传上去，回来常常更难看。</p>\n<p>头像照片是最好的例子。100KB的证件照上传瞬间完成，平台自己的压缩也不会毁掉它的细节。</p>\n<p>封面图要更小心。它们显示得很大，设为横幅之前，先用全尺寸检查结果。</p>\n<p>带文字叠加的帖子，文字要凑近了预览。平台的压缩会让小字变虚，所以要从你能做出的最锐利的100KB文件开始。</p>\n<p>记住每个平台都有自己的上限。压缩之前先查清楚，为一个平台做的文件不一定适合另一个。</p>\n<h2 id=\"storing-100kb-files\">整理你的100KB文件</h2>\n<p>按用途分文件夹存放压缩文件。求职申请一个文件夹，博客图片另一个，就不会弄混。</p>\n<p>文件名里带上尺寸。headshot-100kb.jpg这样的名字，一眼就能看出文件是干什么的。</p>\n<p>原图一定要放在单独的文件夹里。压缩副本是一次性的，原图不是。</p>\n<p>复用之前先检查一遍。一年前做的文件，可能已经不符合你现在要申请的网站的要求了。</p>\n<p>拿不准时，就从原图重新压缩。花一分钟时间，结果一定符合今天的规则。</p>\n<h2 id=\"when-to-move-up\">什么时候升级到200KB？</h2>\n<p>有些图片需要的空间超过100KB。宽幅风景、密集的信息图和细节丰富的商品照，都能从多出来的空间里受益。</p>\n<p>信号就是看得见的发虚。如果100KB下文字模糊、细腻的纹理消失了，这张图片就是在要更大的预算。</p>\n<p>打印是另一个升级的理由。100KB是网页尺寸，任何要印到纸上的东西都应该大得多。</p>\n<p>先看目的地。如果网站或平台允许200KB，就用<a href=\"/zh/tupian-yasuo-dao-200kb/\">200KB压缩工具</a>，而不是和100KB的上限较劲。</p>\n<p>目标始终不变：你的场景允许的最大尺寸，以及这个尺寸能装下的最好画质。</p>\n<h2 id=\"image-weight-budgets\">整个页面的图片重量预算</h2>\n<p>一张100KB的图片很轻，但一个页面有很多张图片。十张缩略图每张100KB，加起来就是1MB，这是页面合理的预算。</p>\n<p>开始之前先定一个总预算。一篇有八张图片的博客文章，每张控制在100KB左右，总共正好在1MB以内。</p>\n<p>优先照顾首图。如果它值得200KB就给它200KB，配图保持在100KB或以下。</p>\n<p>发布后测量真实的页面重量。浏览器的开发者工具能显示总重量，这个数字常常让人意外。</p>\n<p>加载快的页面能留住读者。图片重量通常是最大的影响因素，每张图片100KB是一条可靠的经验法则。</p>\n<h2 id=\"retina-screens\">视网膜屏和高DPI屏幕上的100KB图片</h2>\n<p>视网膜屏在同样的物理尺寸里塞了更多像素。在普通屏幕上锐利的图片，在视网膜屏上可能显得发虚。</p>\n<p>解决方法是提供显示尺寸两倍宽的图片。显示400像素宽的缩略图，文件里就应该是800像素。</p>\n<p>100KB下，800像素的图片依然干净。多出来的像素会占用文件体积，但二分搜索会在画质和预算之间做好平衡。</p>\n<p>小缩略图上这点差别不大。大尺寸的头图上，标准版和视网膜版的差别看得见。</p>\n<p>条件允许时，在真实的高DPI屏幕上测试。看结果的截图会藏住你正想检查的那种发虚。</p>\n<h2 id=\"seasonal-content\">季节性内容与100KB图片的复用</h2>\n<p>博客图片会在不同季节反复使用。一张为某篇文章做的100KB缩略图，可能会再次出现在合集、电子报和社交卡片里。</p>\n<p>把压缩文件和它所属的文章放在一起。共享的缩略图文件夹让复用变得容易，也能避免重复压缩。</p>\n<p>每次复用之前都检查一下。去年看起来不错的缩略图，可能不适合今年的版式或裁剪。</p>\n<p>千万别对复用的文件再压缩一次。需要新尺寸时，回到原图重新压缩。</p>\n<p>好的整理习惯能让100KB的图片变成可复用的资产。现在花一点时间做好命名，以后能省下好几个小时的返工。</p>\n<p>想看动手操作的步骤，可以读<a href=\"/zh/blog/ru-he-ba-tu-pian-suo-xiao-dao-100kb/\">如何把图片缩小到100KB</a>。想看按格式逐一比较的画质分析，可以看<a href=\"/zh/blog/100kb-tu-pian-zhi-liang-jpg-png-webp-dui-bi/\">100KB图片画质：JPG、PNG、WebP对比</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"100KB够用来做职业头像吗？","answer":"够用。100KB的证件照在领英、招聘网站和公司官网上看起来干净又专业。脸部、头发和衣服的细节都能保留，这个大小也几乎能通过所有上传上限。"},{"question":"能把一张10MB的照片压到100KB吗？","answer":"可以，工具接受最大25MB的输入，能把10MB的照片压到100KB以下。二分搜索会找到能塞进去的最高画质，画质不够时尺寸缩放会接着帮忙。细节特别丰富的照片可能会有些发虚，要有心理准备。"},{"question":"压缩到100KB会去掉照片的背景吗？","answer":"不会。压缩只会减小文件体积，不会改动图片的内容。需要去掉背景时，先用背景去除工具处理，再把结果压缩到100KB。"},{"question":"为什么我的PNG截图压缩到100KB后反而变大了？","answer":"用不适合的格式重新编码时，文件可能会变大，工具遇到这种情况会提醒你。把输出换成JPG或WebP通常就能解决，因为这两种格式处理照片和截图的效率远高于PNG。"},{"question":"100KB工具能离线使用吗？","answer":"页面加载完成之后，压缩本身在你的浏览器本地运行，不会上传任何东西。不过第一次加载页面还是需要联网。"},{"question":"怎么确认我的图片真的小于100KB？","answer":"工具会显示结果大小和“小于100KB”的确认信息。你也可以在设备上检查下载的文件，它应该略低于100KB，通常在98KB到99.9KB之间。"}];
